if (!function_exists('labor_merit_rewarder')) {
	function labor_merit_rewarder($purchased_product_id,$userid,$merits) {
		$result = db_query("SELECT DISTINCT c.field_classification_tid AS cat, SUM(h.field_hours_worked_value) AS hours
		FROM {node} node
		LEFT JOIN {field_data_field_project} p ON node.nid = p.entity_id AND (p.entity_type = 'node' AND p.deleted = '0')
		LEFT JOIN {field_data_field_classification} c ON node.nid = c.entity_id AND (c.entity_type = 'node' AND c.deleted = '0')
		LEFT JOIN {field_data_field_hours_worked} h ON node.nid = h.entity_id AND (h.entity_type = 'node' AND h.deleted = '0')
		WHERE p.field_project_target_id = :prid
		AND c.delta = 0
		AND node.uid = :uid 
		AND node.status = '1'
		AND node.type IN  ('work_report')
		GROUP BY c.field_classification_tid", array(':prid' => $purchased_product_id, ':uid' => $userid));
		$resarray = $result->fetchAll();

		$total_time = 0;
		foreach ($resarray as $row) {
			$total_time += $row->hours;
		}
		if ($total_time > 0) {
			foreach ($resarray as $row) {
				$time_share = $row->hours / $total_time;
				rules_invoke_component('rules_update_user_expertise',$time_share,$merits,$row->cat,$userid);
			}
		}
	}
}

if (!function_exists('shares_merit_rewarder')) {
	function shares_merit_rewarder($purchased_product_id,$userid,$merits) {

		$now = time();
		$total_time = rovas_purchase_shares_project_share_hours ($purchased_product_id,$userid);

		if ($total_time > 0) {

			//64.99 Other financial service activities, except insurance and pension funding n.e.c.
			$cat = 1601;
			//load the expert table node corresponding to the current category in order to find its existing Merit value
			$result = db_query("SELECT node.nid AS nid, m.field_merits_value AS merits
			FROM {node} node
			LEFT JOIN {field_data_field_expert} x ON node.nid = x.entity_id AND (x.entity_type = 'node' AND x.deleted = '0')
			LEFT JOIN {field_data_field_category} c ON node.nid = c.entity_id AND (c.entity_type = 'node' AND c.deleted = '0')
			LEFT JOIN {field_data_field_merits} m ON node.nid = m.entity_id AND (m.entity_type = 'node' AND m.deleted = '0')
			WHERE node.type = 'user_expertise'
			AND field_expert_target_id = :uid
			AND c.field_category_tid = :cat
			", array(':uid' => $userid, ':cat' => $cat));

			$record = $result->fetchAssoc();
			//for some users and category IDs we will have to create a new user_expertise node			
			if (empty($record)) {
				$node = new stdClass();
				$node->type = 'user_expertise';
				$node->title = 'UX-' . $userid . '-' . $cat;
				$node->language = LANGUAGE_NONE;
				node_object_prepare($node);
				$node->uid = $userid;

				$node->field_expert[LANGUAGE_NONE][0]['target_id'] = $userid;
				$node->field_category[LANGUAGE_NONE][0]['tid'] = $cat;

				$old_merits = 0;
				$node->field_merits[LANGUAGE_NONE][0]['value'] = $old_merits;

				$node->created = $now;
				$node->changed = $now;

				$node = node_submit($node);
				node_save($node);
				$nid = $node->nid;

			}
			else {
				$old_merits = $record['merits'];
				$nid = $record['nid'];
			}

			$cur_merits = $old_merits + $merits;

			//updating the node with new merit value
			$xobject = entity_metadata_wrapper('node', $nid);
			$xobject->field_merits = $cur_merits;
			$xobject->save();
			
		}
	}
}

if (!function_exists('mrewarder')) {
	function mrewarder($purchased_product_id,$amount_paid,$buyeruid,$receipt_id,$note,&$loopcheck=array()) {

		if (in_array($purchased_product_id,$loopcheck)) {
			return;
		}
		else {
			$loopcheck[]=$purchased_product_id;

			//find total shares and total hours for the purchased project
			$res = db_query("SELECT MIN(node.nid) AS projectid, SUM(ma.field_merit_allocation_value) AS shares, SUM(hw.field_total_hours_worked_value) AS hours
			FROM {node} node
			LEFT JOIN {field_data_field_project} fpr ON node.nid = fpr.entity_id AND (fpr.entity_type = 'node' AND fpr.deleted = '0')
			LEFT JOIN {node} n ON fpr.field_project_target_id = n.nid
			LEFT JOIN {field_data_field_merit_allocation} ma ON node.nid = ma.entity_id AND (ma.entity_type = 'node' AND ma.deleted = '0')
			LEFT JOIN {field_data_field_total_hours_worked} hw ON node.nid = hw.entity_id AND (hw.entity_type = 'node' AND hw.deleted = '0')
			WHERE n.nid = :prid
			AND (node.status = '1' AND node.type IN  ('project_merit_allocation', 'co_worker_merit_allocation', 'timeshare_merit_allocation'))
			", array(':prid' => $purchased_product_id));

			$sumarray = $res->fetchAll();
			//the sum of all partial shares (and hours) from worker and project shareholders
			$tsdiff = 100 - $sumarray[0]->shares;
			$total_hours = $sumarray[0]->hours;

			$result = db_query("SELECT p.entity_id 
			FROM {field_data_field_project} p , {node} n
			WHERE p.bundle IN ('co_worker_merit_allocation','project_merit_allocation','timeshare_merit_allocation')
			AND n.status = 1
			AND n.nid = p.field_project_target_id
			AND p.field_project_target_id = :prid
			ORDER BY p.bundle ASC", array(':prid' => $purchased_product_id));

			$resarray = $result->fetchAll();

			//loop through all shareholders (all types)
			foreach ($resarray as $row) {
				$meritalloc_wrp = entity_metadata_wrapper('node', $row->entity_id);
				$share = $meritalloc_wrp->field_merit_allocation->value();
				$bundle = $meritalloc_wrp->getBundle();

				//processing worker shares, or purchased shares
				if($bundle == 'co_worker_merit_allocation' || $bundle == 'timeshare_merit_allocation') {

					$userid = $meritalloc_wrp->field_coworker->uid->value();
					$hours = $meritalloc_wrp->field_total_hours_worked->value();

					//retrieve the merit decimal part from the user profile
					$merits = ($share/100) * $amount_paid;
					//calculate the total time value of merit reward and add it to the share merit reward
					if($total_hours > 0) {
						$merits = $merits + ($tsdiff/100) * $amount_paid * ($hours/$total_hours);
					}

					switch ($bundle) {
						//reward a user's timeshare with Merits
						case ('timeshare_merit_allocation'):
							shares_merit_rewarder($purchased_product_id,$userid,$merits);
							break;
						//reward a user's labor time with Merits
						default:
							labor_merit_rewarder($purchased_product_id,$userid,$merits);
					}

					//read the merit reward for the user from the merit alloc. record
					$old_merit_val = $meritalloc_wrp->field_merits_earned->value();
					$new_merit_val = $old_merit_val + $merits;
					//update the merit count for the SHAREHOLDER in this project
					$meritalloc_wrp->field_merits_earned = $new_merit_val;
					$meritalloc_wrp->save();

					$user_merit_decimal_part = $meritalloc_wrp->field_coworker->field_merit_decimal_part->value();
					$merits_usrpoints = $merits + $user_merit_decimal_part;

					//calculate whole and decimal part of the reward
					$whole = floor($merits_usrpoints);
					$fraction = $merits_usrpoints - $whole;

					//save the merit decimal part
					$user_wrp = entity_metadata_wrapper('user', $userid);
					$user_wrp->field_merit_decimal_part = $fraction;
					$user_wrp->save(); 

					//record Merits if there are any to reward
					if ($whole != 0) {
						if ($whole > 0)
							$xplain = t('purchased goods or services');
						else
							$xplain = t('was reimbursed for canceled purchase');
						$usrobj = entity_metadata_wrapper('user', $buyeruid);
						$buyername = $usrobj->name->value();
						$buyerfullname = $usrobj->field_full_name->value();
						$params = array (
								'uid' => $userid,
								'points' => $whole,
								'description' => $buyername . ' (' . $buyerfullname . ') ' . $xplain,
								'display' => 0,
								'entity_id' => $purchased_product_id,
								'entity_type' => 'node',
							);
						userpoints_userpointsapi($params);
					}
			
					//create disbursement record, if the user is getting any Merits
					if ($receipt_id > 0 && $merits > 0) {
						$merit_source = ($bundle == 'timeshare_merit_allocation') ? 'charitable_donation' : 'volunteer_work';
							$disburs_id = rules_invoke_component('rules_create_merit_disbursement', $receipt_id, $userid, $merits, $merit_source);
					}
				}

				//processing project_merit_allocation shares
				else if($bundle == 'project_merit_allocation') {
					$shareprojectid = $meritalloc_wrp->field_shareholder_project->nid->value();
					$sh_project_wrp = entity_metadata_wrapper('node', $shareprojectid);
					$timeshare_project_alloc = $meritalloc_wrp->field_share_project_time->value();

					//do not process when the project shareholder nid is the same as the ordered project nid
					//this seems to be an useless/insufficient condition - refactor?
					if ($purchased_product_id != $shareprojectid) {
						//time share product
						if ($timeshare_project_alloc) {

							$hours = $meritalloc_wrp->field_total_hours_worked->value();

							//calculate the total time value of merit reward and add it to the share merit reward
							if($total_hours > 0) {
								$merits = ($tsdiff/100) * $amount_paid * ($hours/$total_hours);
							}
							else {
								$merits = 0;
								break;
							}
						}
						//normal product
						else {
							//calculate the total value of merit reward
							$merits = ($share/100) * $amount_paid;
						}

						//Update the shareholder project merit score
						$calc_merit_val = project_merit_updater($shareprojectid,$merits);
						$meritalloc_wrp->field_merits_earned = $calc_merit_val;
						$meritalloc_wrp->save();

						//only process amounts greater than the smallest value the table can hold.
						if($merits > 0.0000000001) {
							$merit_share = $sh_project_wrp->field_reward_merit_allocation->value()/100;

							//subtract the chron share of the reward and process both parts
							if (!empty($merit_share) && $merit_share < 1) {
								$shareratio = $merit_share / 100;
								$new_merits = $shareratio * $merits;
							
								//transfer a portion of the reward to the project beneficiary
								$chrons4bene = $merits - $new_merits;
	
								$benef_object = $sh_project_wrp->field_chron_beneficiary->value();
	
								if ($benef_object) {
									$beneficiary = $benef_object->uid;
								}
								else {
									$beneficiary = $sh_project_wrp->author->value();
								}

								$buyer = user_load($buyeruid);
								//transfer the chrons
								rules_invoke_component('rules_make_money_transfer',$buyer,$beneficiary,$chrons4bene,$note,TRUE);

								//process the remaining merits
								mrewarder($shareprojectid,$new_merits,$buyeruid,$receipt_id,$note,$loopcheck);
							}
							else {
								mrewarder($shareprojectid,$merits,$buyeruid,$receipt_id,$note,$loopcheck);
							}
						}
						else {
//							watchdog('rule','rules_process_purchase_core; the rules_process_purchase_core asked to store merit reward smaller than allowed by DB schema:' . $merits . ' ME | alloc node ID: ' . $shareprojectid);
						}
					}
				}

			}

		return 'OK';
		//watchdog('debug','END' );
		}
	}
}

